 "Un investisseur propulse {club} en {div}.": "Un inversor catapulta a {club} a {div}.",
 "{seasonClub} évolue désormais en {div} — l'ascension continue.": "{seasonClub} juega ahora en {div}: el ascenso continúa.",
 "{seasonClub} change de dimension et rejoint l'élite européenne.": "{seasonClub} cambia de dimensión y se une a la élite europea.",
 "{seasonClub} n'est plus que l'ombre du géant qu'il fut.": "{seasonClub} ya no es más que la sombra del gigante que fue.",
