 "Rechute en {year} : la convalescence s'éternise.": "Recaída en {year}: la recuperación se eterniza.",
 "Transfert à {toClub} pour {fee}.": "Traspaso a {toClub} por {fee}.",
 "Prêté une saison à {toClub} pour s'aguerrir.": "Cedido una temporada a {toClub} para foguearse.",
 "Retour de prêt convaincant : {parentClub} compte enfin sur vous.": "Cesión convincente: {parentClub} por fin cuenta contigo.",
 "Retour de prêt à {parentClub}, avec une copie honnête.": "Vuelta de la cesión a {parentClub}, con un balance correcto.",
 "Un prêt raté : {parentClub} doute ouvertement de vous.": "Una cesión fallida: {parentClub} duda abiertamente de ti.",
