 "Centre professionnel réputé — un cap sérieux vers le haut niveau": "Cantera profesional reputada: un paso serio hacia el alto nivel",
 "Club formateur solide — du temps de jeu et de vrais éducateurs": "Club formador sólido: minutos y verdaderos formadores",
 "Club modeste mais structuré — peu de moyens, beaucoup de terrain": "Club modesto pero organizado: pocos medios, mucho campo",
 "Petit club discret — loin des projecteurs, mais un vrai tremplin": "Club pequeño y discreto: lejos de los focos, pero un verdadero trampolín",
 "Club local — l'école de la débrouille, près des vôtres": "Club local: la escuela de buscarse la vida, cerca de los tuyos",
 "En finale !": "¡En la final!",
 "Votre nation renverse tout sur son passage : LA FINALE ! À 90 minutes du toit du monde.": "Tu país arrasa con todo a su paso: ¡LA FINAL! A 90 minutos de la cima del mundo.",
