 "Finale continentale perdue": "Final continental perdida",
 "Retrouvailles avec votre ancien club": "Reencuentro con tu antiguo club",
 "Retrouvailles maîtrisées": "Reencuentro bien gestionado",
 "Soirée compliquée": "Noche complicada",
 "Le derby": "El derbi",
 "Derby remporté !": "¡Derbi ganado!",
 "Derby perdu": "Derbi perdido",
 "{sign}{n} Réputation": "{sign}{n} Reputación",
 "🌍 Sélection : {target}": "🌍 Selección: {target}",
 "⬆️ Promu : {role}": "⬆️ Ascendido: {role}",
 "⬇️ Rétrogradé : {role}": "⬇️ Relegado: {role}",
 "⛔ {weeks} semaines hors du groupe": "⛔ {weeks} semanas fuera del grupo",
 "👋 Retraite en fin de saison": "👋 Retirada al final de la temporada",
 "Note de saison ≥ {n}": "Nota de la temporada ≥ {n}",
 "Ramener un trophée majeur": "Traer un gran trofeo",
 "Des écarts d'hygiène de vie répétés se paient sur le terrain.": "Los repetidos excesos fuera del campo se pagan sobre el césped.",
 "🅒 Le vestiaire vous confie le brassard de capitaine.": "🅒 El vestuario te confía el brazalete de capitán.",
 "🎽 Première convocation avec les {tier} de {nat}.": "🎽 Primera convocatoria con la selección {tier} de {nat}.",
 "🏆 Sacre en Coupe Nationale : vous voilà qualifié pour une coupe continentale la saison prochaine !": "🏆 Campeón de la Copa Nacional: ¡ya estás clasificado para una copa continental la próxima temporada!",
 "{name} {year} — le continent à vos pieds.": "{name} {year}: el continente a tus pies.",
 "{club2} n'a pas oublié votre prêt réussi : offre de transfert définitif sur la table.": "{club2} no ha olvidado tu exitosa cesión: hay una oferta de traspaso definitivo sobre la mesa.",
 "Votre contrat expire : il faut trancher.": "Tu contrato expira: hay que decidir.",
 "Vos statistiques n'ont pas convaincu : {club} ne prolonge pas votre contrat. À vous de rebondir ailleurs.": "Tus estadísticas no han convencido: {club} no renueva tu contrato. Te toca rebotar en otro lugar.",
 "La montée de {club} fait de vous une cible : rester pour l'aventure, ou viser encore plus haut ?": "El ascenso de {club} te convierte en un objetivo: ¿quedarte para la aventura o apuntar aún más alto?",
 "La relégation de {club} ouvre votre bon de sortie.": "El descenso de {club} te abre la puerta de salida.",
 "Votre temps de jeu famélique alerte tout le marché.": "Tus escasos minutos han puesto en alerta a todo el mercado.",
 "Votre saison XXL affole les recruteurs.": "Tu temporada descomunal vuelve locos a los ojeadores.",
 "Le club vous a placé sur la liste des transferts : le marché s'organise.": "El club te ha puesto en la lista de transferibles: el mercado se mueve.",
 "Le mercato s'agite autour de votre nom.": "El mercado de fichajes se agita en torno a tu nombre.",
 "L'élite vous juge trop vieux, mais un gardien chevronné trouve toujours preneur, un ou deux crans plus bas.": "La élite te considera demasiado mayor, pero un portero veterano siempre encuentra comprador, uno o dos escalones más abajo.",
 "Passé 42 ans, plus aucun cador ne mise sur vous : seuls des clubs modestes vous ouvrent encore leurs portes.": "Pasados los 42, ningún grande apuesta ya por ti: solo los clubes modestos te abren aún sus puertas.",
 "Trop juste pour ce niveau : le club vous remercie. Direction l'échelon inférieur pour vous relancer.": "No llegas al nivel: el club prescinde de ti. Toca bajar de categoría para relanzarte.",
 "Le destin ne vous aura pas laissé la moindre chance de rivaliser. {rival} aura eu l'opportunité de construire la carrière qui vous a échappé.": "El destino no te dio la menor oportunidad de competir. {rival} pudo construir la carrera que a ti se te escapó.",
 "{rival} n'aura même pas eu la chance de faire ses preuves. Le destin vous aura été bien plus favorable qu'à lui.": "{rival} ni siquiera tuvo la oportunidad de demostrar su valía. El destino fue mucho más generoso contigo.",
 "Vous surpassez très largement {rival} : cette rivalité n'en aura jamais vraiment été une.": "Superas con creces a {rival}: esta rivalidad nunca llegó a serlo de verdad.",
 "Vous prenez clairement le dessus sur {rival} au fil des années.": "Te impusiste claramente a {rival} con el paso de los años.",
 "Une rivalité aussi intense que serrée avec {rival} — tout aurait pu basculer à tout moment.": "Una rivalidad tan intensa como igualada con {rival}: todo podía decantarse en cualquier momento.",
 "{rival} vous aura devancé sur la majeure partie de votre carrière.": "{rival} estuvo por delante de ti durante la mayor parte de tu carrera.",
 "{rival} aura eu la carrière que vous auriez rêvé d'avoir.": "{rival} tuvo la carrera con la que tú habrías soñado.",
 "Carrière jamais commencée": "Una carrera que nunca empezó",
 "Un diagnostic médical implacable a mis fin à vos espoirs avant même vos débuts professionnels. Une histoire qui aurait pu être si différente.": "Un diagnóstico médico implacable acabó con tus esperanzas antes incluso de tu debut profesional. Una historia que podría haber sido muy distinta.",
 "Carrière écourtée par la blessure": "Carrera acortada por una lesión",
 "Une blessure de trop a refermé le rideau plus tôt que vous ne l'auriez voulu. Mais le chemin parcouru, lui, personne ne pourra vous l'enlever.": "Una lesión de más bajó el telón antes de lo que habrías querido. Pero el camino recorrido nadie te lo podrá quitar.",
 "Carrière fauchée en plein vol": "Una carrera segada en pleno vuelo",
 "En pleine ascension, une blessure implacable a tout arrêté net. On ne saura jamais jusqu'où vous seriez allé — et c'est peut-être ça, le plus cruel.": "En pleno ascenso, una lesión implacable lo detuvo todo en seco. Nunca sabremos hasta dónde habrías llegado, y quizá eso sea lo más cruel.",
 "Carrière brisée": "Carrera truncada",
 "Une blessure sévère a stoppé net votre progression, alors que tout semblait encore possible. Le destin en a décidé autrement.": "Una lesión grave frenó en seco tu progresión cuando todo parecía aún posible. El destino decidió otra cosa.",
 "Star inattendue": "Estrella inesperada",
 "Rien ne laissait présager un tel sommet, et pourtant vous avez soulevé le plus grand des trophées. Une carrière que personne n'avait vue venir.": "Nada hacía presagiar semejante cima y, sin embargo, levantaste el mayor de los trofeos. Una carrera que nadie vio venir.",
 "Légende du football mondial": "Leyenda del fútbol mundial",
 "Votre nom restera gravé parmi les plus grands. Les gamins du monde entier porteront votre maillot pendant des décennies.": "Tu nombre quedará grabado entre los más grandes. Niños de todo el mundo llevarán tu camiseta durante décadas.",
 "Star mondiale": "Estrella mundial",
 "Vous avez marqué votre époque et forcé le respect de tout un sport, bien au-delà des frontières de vos clubs.": "Marcaste tu época y te ganaste el respeto de todo un deporte, mucho más allá de las fronteras de tus clubes.",
 "Joueur de classe internationale": "Jugador de talla internacional",
 "Une carrière remarquable, de celles qui remplissent les stades et les albums de vignettes.": "Una carrera notable, de las que llenan estadios y álbumes de cromos.",
 "Carrière solide et respectée": "Una carrera sólida y respetada",
 "Sans être une superstar, vous avez mené une carrière dont vous pouvez être fier, reconnue par vos pairs.": "Sin ser una superestrella, tuviste una carrera de la que puedes estar orgulloso, reconocida por tus compañeros de profesión.",
 "Honnête professionnel": "Un profesional honrado",
 "Une carrière sans éclat majeur, mais menée avec sérieux jusqu'au bout, loin des projecteurs.": "Una carrera sin grandes brillos, pero llevada con seriedad hasta el final, lejos de los focos.",
 "Carrière discrète": "Una carrera discreta",
 "Le grand public ne retiendra pas votre nom, mais vous avez vécu de votre passion, et ça n'a pas de prix.": "El gran público no recordará tu nombre, pero viviste de tu pasión, y eso no tiene precio.",
